WITH metrics AS (SELECT id, channel, discount_pct, NTILE(4) OVER (PARTITION BY promo_code ORDER BY discount_pct DESC, id) AS discount_pct_bucket, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY ends_on, id) AS seq_no, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('week', starts_on), promo_code ORDER BY discount_pct, id) AS row_seq, AVG(discount_pct) OVER (ORDER BY ends_on, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS discount_pct_avg_2 FROM promotions WHERE YEAR(starts_on) = 2023) SELECT id, channel, discount_pct_bucket, seq_no, row_seq, discount_pct_avg_2, CASE WHEN channel RLIKE '^(web|mobile)$' THEN 'CORE' ELSE 'EXTENDED' END AS channel_zone FROM metrics;
